// Graph impact size for a session (DESIGN.md §"Difficulty and review"). Primary method: spawn
// `entire graph impact --symbol <s> --format json` for the symbols declared in the touched hunks of
// the session's commit, and sum caller and type-consumer counts. When entire is not installed or
// fails, fall back to the import fan-in of the touched files. The method used is always returned.

import { dirname, join, normalize } from "node:path";

export type ImpactMethod = "graph" | "fan-in";

export interface ImpactResult {
  size: number;
  method: ImpactMethod;
  /** Symbols queried with the graph; empty for fan-in. */
  symbols: string[];
}

export interface GraphOptions {
  /** Binary to spawn; default `entire` from PATH. */
  entireBin?: string;
  /** Per-call timeout in ms. */
  timeoutMs?: number;
  /** Max symbols queried per session. */
  maxSymbols?: number;
}

export const DEFAULT_TIMEOUT_MS = 30_000;
export const DEFAULT_MAX_SYMBOLS = 8;

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return { ok: p.exitCode === 0, out: p.stdout.toString() };
}

const DECL =
  /^\s*(?:export\s+)?(?:default\s+)?(?:declare\s+)?(?:async\s+)?(?:abstract\s+)?(?:function\*?|class|interface|type|enum|const|let|var)\s+([A-Za-z_$][\w$]*)/;

/** Names declared on the added lines of `sha`'s diff, in diff order, deduplicated. */
export function symbolsInHunks(repo: string, sha: string): string[] {
  const r = git(repo, ["show", "--unified=0", "--format=", "--no-color", "--no-renames", sha]);
  if (!r.ok) return [];
  const seen = new Set<string>();
  for (const line of r.out.split("\n")) {
    if (!line.startsWith("+") || line.startsWith("+++")) continue;
    const m = DECL.exec(line.slice(1));
    if (m?.[1]) seen.add(m[1]);
  }
  return [...seen];
}

/** Callers plus type consumers in one `entire graph impact` JSON reply; null when it is not one. */
export function parseImpact(json: string): number | null {
  try {
    const j = JSON.parse(json) as {
      disambiguation_required?: boolean;
      focus?: unknown;
      callers?: { total?: number };
      type_consumers?: { total?: number };
    };
    if (!j || typeof j !== "object" || !j.focus) return null;
    return (j.callers?.total ?? 0) + (j.type_consumers?.total ?? 0);
  } catch {
    return null;
  }
}

/** One spawned impact query. `null` = the graph could not answer (missing binary, timeout, error). */
export function graphImpact(repo: string, symbol: string, opts: GraphOptions = {}): number | null {
  const bin = opts.entireBin ?? "entire";
  let p: ReturnType<typeof Bun.spawnSync>;
  try {
    p = Bun.spawnSync(
      [bin, "graph", "impact", "--repo", repo, "--symbol", symbol, "--format", "json", "--depth", "2"],
      { cwd: repo, stdout: "pipe", stderr: "pipe", timeout: opts.timeoutMs ?? DEFAULT_TIMEOUT_MS },
    );
  } catch {
    return null;
  }
  if (p.exitCode !== 0 || !p.stdout) return null;
  return parseImpact(p.stdout.toString());
}

// ---------- fallback: import fan-in ----------

const IMPORT = /(?:\bfrom\s*|\bimport\s*\(?\s*|\brequire\s*\(\s*)["'](\.{1,2}\/[^"']+)["']/g;
const SOURCE = /\.(?:[cm]?[jt]sx?)$/;
const stripExt = (p: string) => p.replace(SOURCE, "").replace(/\/index$/, "");

const fanInCache = new Map<string, Map<string, number>>();

/** Module (path without extension) → number of distinct files at HEAD that import it relatively. */
export function importFanIn(repo: string): Map<string, number> {
  const head = git(repo, ["rev-parse", "HEAD"]).out.trim();
  const key = `${repo}@${head}`;
  const cached = fanInCache.get(key);
  if (cached) return cached;
  const counts = new Map<string, number>();
  const grep = git(repo, ["grep", "-I", "-E", "(from|import|require)", "HEAD", "--", "*.ts", "*.tsx", "*.js", "*.jsx", "*.mjs", "*.cjs", "*.mts", "*.cts"]);
  const importers = new Map<string, Set<string>>();
  for (const line of grep.out.split("\n")) {
    // `HEAD:path:content`
    const m = /^HEAD:([^:]+):(.*)$/.exec(line);
    if (!m) continue;
    const [, file, content] = m as unknown as [string, string, string];
    for (const im of content.matchAll(IMPORT)) {
      const target = stripExt(normalize(join(dirname(file), im[1]!)));
      if (target === stripExt(file)) continue;
      let set = importers.get(target);
      if (!set) importers.set(target, (set = new Set()));
      set.add(file);
    }
  }
  for (const [t, s] of importers) counts.set(t, s.size);
  fanInCache.set(key, counts);
  return counts;
}

export function fanInSize(repo: string, files: string[]): number {
  const counts = importFanIn(repo);
  return files.reduce((sum, f) => sum + (counts.get(stripExt(normalize(f))) ?? 0), 0);
}

// ---------- per session ----------

/**
 * Impact size of a session's change. Graph when entire answers for every queried symbol; otherwise
 * fan-in over `files`. A session with no commit or no declared symbols uses fan-in.
 */
export function impactSize(repo: string, sha: string | null, files: string[], opts: GraphOptions = {}): ImpactResult {
  const symbols = sha ? symbolsInHunks(repo, sha).slice(0, opts.maxSymbols ?? DEFAULT_MAX_SYMBOLS) : [];
  if (symbols.length > 0) {
    let size = 0;
    let ok = true;
    for (const s of symbols) {
      const n = graphImpact(repo, s, opts);
      if (n === null) {
        ok = false;
        break;
      }
      size += n;
    }
    if (ok) return { size, method: "graph", symbols };
  }
  return { size: fanInSize(repo, files), method: "fan-in", symbols: [] };
}

// Per-session difficulty (DESIGN.md §"Difficulty and review"): the mean z-score, over the sessions
// being compared, of log(1 + lines changed), files touched, graph impact size and first-prompt
// length. Terciles split the sessions by that score so setups are compared like for like.

import type { Session, Tercile } from "../types.ts";
import { impactSize, type GraphOptions, type ImpactMethod } from "./graph.ts";

export type { ImpactMethod } from "./graph.ts";

export interface DifficultyFeatures {
  /** Added + deleted lines in the session's commit; null when the session has no commit. */
  lines_changed: number | null;
  files_touched: number;
  impact: number;
  /** Which impact method produced `impact`. */
  impact_method: ImpactMethod;
  first_prompt_len: number;
}

export interface DifficultyScore {
  session_id: string;
  features: DifficultyFeatures;
  difficulty: number;
  tercile: Tercile;
}

function git(repo: string, args: string[]): { ok: boolean; out: string } {
  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  return { ok: p.exitCode === 0, out: p.stdout.toString() };
}

/** Lines and files changed by `sha` (binary files count as one file, zero lines). */
export function commitChange(repo: string, sha: string): { lines: number; files: string[] } | null {
  const r = git(repo, ["show", "--numstat", "--format=", "--no-renames", sha]);
  if (!r.ok) return null;
  let lines = 0;
  const files: string[] = [];
  for (const row of r.out.split("\n")) {
    const [add, del, path] = row.split("\t");
    if (path === undefined) continue;
    files.push(path);
    lines += (Number(add) || 0) + (Number(del) || 0);
  }
  return { lines, files };
}

/** Raw difficulty features of one session. */
export function features(session: Session, repo: string, opts: GraphOptions = {}): DifficultyFeatures {
  const change = session.commit_sha ? commitChange(repo, session.commit_sha) : null;
  const files = session.files.length > 0 ? session.files : change?.files ?? [];
  const impact = impactSize(repo, change ? session.commit_sha : null, files, opts);
  return {
    lines_changed: change?.lines ?? null,
    files_touched: files.length,
    impact: impact.size,
    impact_method: impact.method,
    first_prompt_len: session.first_prompt.length,
  };
}

/** z-scores of `xs`; missing values and zero-variance columns score 0 (the mean). */
export function zScores(xs: (number | null)[]): number[] {
  const present = xs.filter((x): x is number => x !== null);
  if (present.length === 0) return xs.map(() => 0);
  const mean = present.reduce((s, x) => s + x, 0) / present.length;
  const sd = Math.sqrt(present.reduce((s, x) => s + (x - mean) ** 2, 0) / present.length);
  return xs.map((x) => (x === null || sd === 0 ? 0 : (x - mean) / sd));
}

/** Mean z-score of the four features, per row, relative to all rows given. */
export function difficultyFromFeatures(rows: DifficultyFeatures[]): number[] {
  const cols = [
    zScores(rows.map((f) => (f.lines_changed === null ? null : Math.log1p(f.lines_changed)))),
    zScores(rows.map((f) => f.files_touched)),
    zScores(rows.map((f) => f.impact)),
    zScores(rows.map((f) => f.first_prompt_len)),
  ];
  return rows.map((_, i) => cols.reduce((s, c) => s + c[i]!, 0) / cols.length);
}

/**
 * Terciles by rank: the lowest third of scores is 1, the highest third 3. Ties break by id so the
 * split is deterministic.
 */
export function terciles<T extends { session_id: string; difficulty: number }>(rows: T[]): Map<string, Tercile> {
  const sorted = [...rows].sort(
    (a, b) => a.difficulty - b.difficulty || (a.session_id < b.session_id ? -1 : a.session_id > b.session_id ? 1 : 0),
  );
  const out = new Map<string, Tercile>();
  sorted.forEach((r, i) => out.set(r.session_id, (Math.floor((3 * i) / sorted.length) + 1) as Tercile));
  return out;
}

/** Difficulty and tercile of every session, scored against the others in `sessions`. */
export function difficulty(sessions: Session[], repo: string, opts: GraphOptions = {}): DifficultyScore[] {
  const feats = sessions.map((s) => features(s, repo, opts));
  const scores = difficultyFromFeatures(feats);
  const rows = sessions.map((s, i) => ({ session_id: s.id, features: feats[i]!, difficulty: scores[i]! }));
  const t = terciles(rows);
  return rows.map((r) => ({ ...r, tercile: t.get(r.session_id)! }));
}

import { afterAll, beforeAll, describe, expect, setDefaultTimeout, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

import { difficulty, difficultyFromFeatures, features, terciles, zScores, type DifficultyScore } from "../src/difficulty/index.ts";
import { fanInSize, graphImpact, impactSize, parseImpact, symbolsInHunks } from "../src/difficulty/graph.ts";
import { identify } from "../src/identity/index.ts";
import { parseCheckpoints } from "../src/ingest/parse.ts";
import type { Session } from "../src/types.ts";
import { git, makeFixture } from "./fixtures/make-fixture.ts";

setDefaultTimeout(120_000);

const root = mkdtempSync(join(tmpdir(), "roster-difficulty-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));

const NO_GRAPH = { entireBin: join(root, "no-such-entire") };
const hasEntire = Bun.which("entire") !== null;

/** A tiny repo with relative imports, committed with the fixture's git env. */
function importRepo(dir: string): { repo: string; sha: string } {
  mkdirSync(dir, { recursive: true });
  git(dir, ["init", "-q", "-b", "main"]);
  const files: Record<string, string> = {
    "src/util.ts": "export function helper(x: number): number {\n  return x + 1;\n}\n",
    "src/a.ts": 'import { helper } from "./util.ts";\nexport const a = helper(1);\n',
    "src/b.ts": 'import { helper } from "./util";\nexport const b = helper(2);\n',
    "src/c/index.ts": 'export { a } from "../a.ts";\n',
  };
  for (const [p, c] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, p)), { recursive: true });
    writeFileSync(join(dir, p), c);
  }
  git(dir, ["add", "-A"]);
  git(dir, ["commit", "-q", "--no-gpg-sign", "-m", "init"]);
  return { repo: dir, sha: git(dir, ["rev-parse", "HEAD"]) };
}

describe("z-scores and terciles", () => {
  test("zScores: mean 0, missing and constant columns score 0", () => {
    const z = zScores([1, 2, 3, null]);
    expect(z[0]! + z[1]! + z[2]!).toBeCloseTo(0);
    expect(z[1]).toBe(0);
    expect(z[3]).toBe(0);
    expect(zScores([5, 5, 5])).toEqual([0, 0, 0]);
  });

  test("difficulty is the mean of four z-scores and orders by size", () => {
    const f = (lines: number, files: number, impact: number, len: number) => ({
      lines_changed: lines,
      files_touched: files,
      impact,
      impact_method: "fan-in" as const,
      first_prompt_len: len,
    });
    const d = difficultyFromFeatures([f(1, 1, 0, 10), f(10, 2, 1, 50), f(100, 3, 2, 90)]);
    expect(d[0]!).toBeLessThan(d[1]!);
    expect(d[1]!).toBeLessThan(d[2]!);
    expect(d[0]! + d[1]! + d[2]!).toBeCloseTo(0);
  });

  test("terciles split by rank into thirds", () => {
    const rows = Array.from({ length: 9 }, (_, i) => ({ session_id: `s${i}`, difficulty: i }));
    const t = terciles(rows);
    expect(rows.map((r) => t.get(r.session_id))).toEqual([1, 1, 1, 2, 2, 2, 3, 3, 3]);
  });
});

describe("impact methods", () => {
  test("fan-in counts distinct relative importers at HEAD", () => {
    const { repo } = importRepo(join(root, "imports"));
    expect(fanInSize(repo, ["src/util.ts"])).toBe(2);
    expect(fanInSize(repo, ["src/a.ts"])).toBe(1);
    expect(fanInSize(repo, ["src/b.ts", "src/c/index.ts"])).toBe(0);
  });

  test("symbols come from declarations on the touched hunks", () => {
    const { repo, sha } = importRepo(join(root, "symbols"));
    expect(symbolsInHunks(repo, sha).sort()).toEqual(["a", "b", "helper"]);
  });

  test("graph unavailable → fan-in is used and recorded", () => {
    const { repo, sha } = importRepo(join(root, "nograph"));
    expect(graphImpact(repo, "helper", NO_GRAPH)).toBeNull();
    const r = impactSize(repo, sha, ["src/util.ts"], NO_GRAPH);
    expect(r).toEqual({ size: 2, method: "fan-in", symbols: [] });
  });

  test.skipIf(!hasEntire)("entire graph available → graph is used and recorded", () => {
    const { repo, sha } = importRepo(join(root, "graph"));
    const raw = Bun.spawnSync(["entire", "graph", "impact", "--repo", repo, "--symbol", "helper", "--format", "json"], {
      cwd: repo,
      stdout: "pipe",
      stderr: "pipe",
      timeout: 60_000,
    });
    const n = parseImpact(raw.stdout.toString());
    expect(n).not.toBeNull();
    expect(n!).toBeGreaterThan(0);
    const r = impactSize(repo, sha, ["src/util.ts"], { timeoutMs: 60_000 });
    expect(r.method).toBe("graph");
    expect(r.symbols.sort()).toEqual(["a", "b", "helper"]);
    expect(r.size).toBeGreaterThanOrEqual(n!);
  });

  test("parseImpact rejects non-impact output", () => {
    expect(parseImpact("not json")).toBeNull();
    expect(parseImpact("{}")).toBeNull();
  });
});

describe("confound fixture (X gets only the hard tasks)", () => {
  let sessions: Session[];
  let scores: DifficultyScore[];
  const tagOf = new Map<string, string>();

  beforeAll(() => {
    const dir = join(root, "confound");
    makeFixture(dir, "confound");
    sessions = parseCheckpoints(dir, "branch", { warn: () => {} }).map((s) => {
      const id = identify(s, dir);
      if (id.tag) tagOf.set(s.id, id.tag.setup);
      return { ...s, setup_id: id.setupId };
    });
    scores = difficulty(sessions, dir, NO_GRAPH);
  });

  const of = (setup: string) => scores.filter((s) => tagOf.get(s.session_id) === setup);

  test("every session is scored; graph unavailable → fan-in recorded on each", () => {
    expect(scores.length).toBe(27);
    expect(new Set(scores.map((s) => s.features.impact_method))).toEqual(new Set(["fan-in"]));
    for (const s of scores) expect(s.features.lines_changed).not.toBeNull();
  });

  test("X's sessions land in the top tercile, never the bottom", () => {
    const x = of("X");
    expect(x.length).toBe(9);
    expect(x.every((s) => s.tercile >= 2)).toBe(true);
    const top = scores.filter((s) => s.tercile === 3);
    const xTop = top.filter((s) => tagOf.get(s.session_id) === "X").length;
    // X holds more of the top tercile than Y and Z, and more than its 1/3 base share.
    expect(xTop).toBeGreaterThan(top.length / 3);
    for (const other of ["Y", "Z"]) expect(xTop).toBeGreaterThan(of(other).filter((s) => s.tercile === 3).length);
    const mean = (r: DifficultyScore[]) => r.reduce((a, s) => a + s.difficulty, 0) / r.length;
    expect(mean(x)).toBeGreaterThan(mean(of("Y")));
    expect(mean(x)).toBeGreaterThan(mean(of("Z")));
  });

  test("small tasks of Y and Z land in the bottom tercile", () => {
    const small = scores.filter((s) => s.features.files_touched === 1);
    expect(small.length).toBe(6);
    expect(small.every((s) => s.tercile === 1)).toBe(true);
  });

  test("features match the session's commit", () => {
    const s = sessions.find((x) => tagOf.get(x.id) === "X")!;
    const f = features(s, join(root, "confound"), NO_GRAPH);
    expect(f.files_touched).toBe(3);
    expect(f.first_prompt_len).toBe(s.first_prompt.length);
  });
});

